@push('scripts')<script>document.getElementById('foto').addEventListener('change',function(){const imagem=document.getElementById('previa-foto');if(imagem.dataset.url)URL.revokeObjectURL(imagem.dataset.url);if(this.files[0]){imagem.dataset.url=URL.createObjectURL(this.files[0]);imagem.src=imagem.dataset.url;imagem.classList.remove('d-none');}else imagem.classList.add('d-none');});</script>@endpush
